// In-memory cache for fast repeated queries
const serverCache = new Map<string, any>();

function cleanArtistVariants(artist: string): string[] {
  const raw = (artist || '').trim();
  if (!raw) return [];

  const stripped = raw
    .replace(/\s*\(\d+\)\s*$/g, '') // remove Discogs numbers like (2)
    .replace(/["']/g, '')
    .trim();

  const variants = new Set<string>();
  variants.add(stripped);

  // Invert "Name, The" -> "The Name" (e.g. "Beatles, The" -> "The Beatles")
  if (/,\s*The$/i.test(stripped)) {
    variants.add(`The ${stripped.replace(/,\s*The$/i, '').trim()}`);
  }

  // Invert "Lastname, Firstname" -> "Firstname Lastname" (e.g. "Bowie, David" -> "David Bowie")
  if (stripped.includes(',') && !stripped.includes('&') && !stripped.includes('and')) {
    const parts = stripped.split(',').map((p) => p.trim());
    if (parts.length === 2 && parts[0] && parts[1]) {
      variants.add(`${parts[1]} ${parts[0]}`);
    }
  }

  // Handle "&" and "and"
  if (stripped.includes('&')) {
    variants.add(stripped.replace('&', 'and'));
    const firstArtist = stripped.split('&')[0].trim();
    if (firstArtist) variants.add(firstArtist);
  } else if (/\band\b/i.test(stripped)) {
    variants.add(stripped.replace(/\band\b/gi, '&'));
    const firstArtist = stripped.split(/\band\b/i)[0].trim();
    if (firstArtist) variants.add(firstArtist);
  }

  // Remove accents / diacritics (e.g. "Mötley Crüe" -> "Motley Crue")
  for (const v of Array.from(variants)) {
    const unaccented = v.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (unaccented !== v) {
      variants.add(unaccented);
    }
  }

  return Array.from(variants).filter(Boolean);
}

function cleanTitleVariants(title: string): string[] {
  const base = (title || '')
    .replace(/^["'\s]+|["'\s]+$/g, '')
    .replace(/^\.{2,}/, '')
    .replace(/★/g, 'Blackstar')
    .replace(/^\d+\.\s*/, '')
    .replace(/["']/g, '')
    .trim();

  const variants = new Set<string>();
  variants.add(base);

  const baseLower = base.toLowerCase();
  // Special titles and aliases
  if (baseLower === 'untitled') {
    variants.add('Led Zeppelin IV');
    variants.add('IV');
  }
  if (baseLower.includes('★') || baseLower.includes('blackstar')) {
    variants.add('Blackstar');
  }
  if (baseLower.includes('ziggy stardust')) {
    variants.add('Ziggy Stardust');
  }
  if (baseLower.startsWith('...nothing like the sun')) {
    variants.add('Nothing Like The Sun');
  }
  if (baseLower.startsWith('...nada como el sol')) {
    variants.add('Nada Como El Sol');
  }
  if (baseLower.includes('outside (the nathan adler')) {
    variants.add('Outside');
  }
  if (baseLower.includes('satisfaction / con le mie lacrime')) {
    variants.add('Satisfaction');
    variants.add('Con Le Mie Lacrime');
  }
  if (baseLower.includes('(she\'s) sexy + 17')) {
    variants.add('Sexy + 17');
    variants.add('Sexy and 17');
  }

  // Strip parentheses and brackets e.g. "(Remastered 2021)" or "[Vinyl LP]"
  const cleanParentheses = base
    .replace(/\s*\(.*?\)\s*/g, ' ')
    .replace(/\s*\[.*?\]\s*/g, ' ')
    .replace(/\b(2xLP|LP|CD|Album|EP|MiniAlbum|Comp|Deluxe|Edition|Remastered|Unofficial|RP|Gat|Ltd|Num|Pic|Son|Car|Dig)\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (cleanParentheses) variants.add(cleanParentheses);

  // Strip common suffixes like "- 2011 Remaster", "- Remastered", "- Live"
  const cleanSuffixes = cleanParentheses
    .replace(/\s*-\s*(?:remaster|deluxe|edition|anniversary|version|live|popular favorites|mono|stereo|original).*/gi, '')
    .trim();
  if (cleanSuffixes) variants.add(cleanSuffixes);

  // Split on "/" or "•" for double/split albums
  if (cleanParentheses.includes('/')) {
    const firstPart = cleanParentheses.split('/')[0].trim();
    if (firstPart) variants.add(firstPart);
  }
  if (cleanParentheses.includes('•')) {
    const firstPart = cleanParentheses.split('•')[0].trim();
    if (firstPart) variants.add(firstPart);
  }

  // Accent normalization
  for (const v of Array.from(variants)) {
    const unaccented = v.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (unaccented !== v) {
      variants.add(unaccented);
    }
  }

  return Array.from(variants).filter(Boolean);
}

function normalizeMatchText(s?: string): string {
  if (!s) return '';
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s*\(\d+\)$/, '') // remove Discogs numbering e.g. (2)
    .replace(/^the\s+/, '')
    .replace(/[^a-z0-9]/g, '');
}

function isArtistMatch(targetArtist: string, candidateArtist?: string): boolean {
  if (!candidateArtist) return false;
  const t = normalizeMatchText(targetArtist);
  const c = normalizeMatchText(candidateArtist);
  if (!t || !c) return false;

  // Exact normalized match
  if (t === c) return true;

  // Disallow obvious tribute bands, karaoke, or karaoke backing artists
  const candLower = candidateArtist.toLowerCase();
  if (
    candLower.includes('tribute') ||
    candLower.includes('karaoke') ||
    candLower.includes('in the style of') ||
    candLower.includes('originally performed') ||
    (candLower.includes('orchestra') && !targetArtist.toLowerCase().includes('orchestra')) ||
    (candLower.includes('string quartet') && !targetArtist.toLowerCase().includes('string quartet')) ||
    candLower.includes('instrumental version')
  ) {
    return false;
  }

  // Substring match with minimum character check to avoid false positives (e.g. "Bowe" vs "Bowie")
  if (t.includes(c) || c.includes(t)) {
    const minLen = Math.min(t.length, c.length);
    if (minLen >= 4) return true;
  }

  // Word token overlap for joint credits (e.g. "Brian Eno & David Byrne" or "Carmine Coppola And Francis Ford Coppola")
  const tWords = targetArtist.toLowerCase().split(/[\s,&/-]+/).filter((w) => w.length > 2 && w !== 'the' && w !== 'and');
  const cWords = candidateArtist.toLowerCase().split(/[\s,&/-]+/).filter((w) => w.length > 2 && w !== 'the' && w !== 'and');
  const matchedWords = tWords.filter((w) => cWords.includes(w));
  if (matchedWords.length > 0 && matchedWords.length >= Math.min(tWords.length, cWords.length)) {
    return true;
  }

  return false;
}

function isAlbumMatch(targetAlbum: string, candidateAlbum?: string): boolean {
  if (!candidateAlbum) return false;
  const t = normalizeMatchText(targetAlbum);
  const c = normalizeMatchText(candidateAlbum);
  if (!t || !c) return false;

  if (t === c || t.includes(c) || c.includes(t)) return true;

  // Clean subtitles before colon, hyphen, or paren
  const cleanT = normalizeMatchText(targetAlbum.split(/[:\-\(]/)[0]);
  const cleanC = normalizeMatchText(candidateAlbum.split(/[:\-\(]/)[0]);
  if (cleanT && cleanC && (cleanT === cleanC || cleanT.includes(cleanC) || cleanC.includes(cleanT))) {
    return true;
  }

  // Led Zeppelin Untitled / IV alias
  if (
    (targetAlbum.toLowerCase().includes('untitled') || targetAlbum.toLowerCase().includes('iv')) &&
    (candidateAlbum.toLowerCase().includes('untitled') || candidateAlbum.toLowerCase().includes('iv') || candidateAlbum.toLowerCase().includes('four'))
  ) {
    return true;
  }

  return false;
}

