/**
 * In-Memory Asynchronous Queue Rate Limiter & LRU Response Cache.
 * Protects APIs from rate limiting, with special enforcement for MusicBrainz (1 req/sec)
 * and automatic retry with exponential backoff on 429 / 503.
 */

export interface RateLimiterOptions {
  name: string;
  minIntervalMs: number; // e.g. 1050ms for MusicBrainz, 200ms for others
  maxRequestsPerMinute?: number;
  maxRetries?: number;
  defaultTtlMs?: number; // cache TTL, default 15 minutes
}

interface CacheEntry<T> {
  data: T;
  expiresAt: number;
}

export class RateLimiter {
  private name: string;
  private minIntervalMs: number;
  private maxRetries: number;
  private defaultTtlMs: number;
  private lastRequestTimestamp: number = 0;
  private queue: Array<() => void> = [];
  private isProcessing: boolean = false;
  private cache = new Map<string, CacheEntry<any>>();
  private totalRequests: number = 0;
  private totalErrors: number = 0;

  constructor(options: RateLimiterOptions) {
    this.name = options.name;
    this.minIntervalMs = Math.max(10, options.minIntervalMs);
    this.maxRetries = options.maxRetries ?? 3;
    this.defaultTtlMs = options.defaultTtlMs ?? 15 * 60 * 1000; // 15 mins default
  }

  public getStats() {
    return {
      name: this.name,
      minIntervalMs: this.minIntervalMs,
      totalRequests: this.totalRequests,
      totalErrors: this.totalErrors,
      queueLength: this.queue.length,
      cachedEntries: this.cache.size,
      lastRequestTimestamp: this.lastRequestTimestamp,
    };
  }

  /**
   * Acquire a turn in the rate-limited queue.
   */
  private async acquireSlot(): Promise<void> {
    return new Promise((resolve) => {
      this.queue.push(resolve);
      this.processQueue();
    });
  }

  private async processQueue() {
    if (this.isProcessing || this.queue.length === 0) return;
    this.isProcessing = true;

    while (this.queue.length > 0) {
      const now = Date.now();
      const timeSinceLast = now - this.lastRequestTimestamp;
      const waitTime = Math.max(0, this.minIntervalMs - timeSinceLast);

      if (waitTime > 0) {
        await new Promise((r) => setTimeout(r, waitTime));
      }

      this.lastRequestTimestamp = Date.now();
      const next = this.queue.shift();
      if (next) {
        next();
      }
    }

    this.isProcessing = false;
  }

  /**
   * Check cache or execute a rate-limited fetch with automatic retry on 429 / 503.
   */
  public async execute<T>(
    cacheKey: string | null,
    fn: () => Promise<T>,
    customTtlMs?: number
  ): Promise<T> {
    // 1. Check cache if key provided
    if (cacheKey) {
      const cached = this.cache.get(cacheKey);
      if (cached && cached.expiresAt > Date.now()) {
        return cached.data as T;
      }
    }

    let attempt = 0;
    let lastError: any = null;

    while (attempt <= this.maxRetries) {
      attempt++;
      await this.acquireSlot();
      this.totalRequests++;

      try {
        const result = await fn();

        // Save to cache
        if (cacheKey && result !== null && result !== undefined) {
          // Keep max 500 cached entries
          if (this.cache.size > 500) {
            const oldestKey = this.cache.keys().next().value;
            if (oldestKey) this.cache.delete(oldestKey);
          }
          this.cache.set(cacheKey, {
            data: result,
            expiresAt: Date.now() + (customTtlMs ?? this.defaultTtlMs),
          });
        }

        return result;
      } catch (err: any) {
        lastError = err;
        this.totalErrors++;

        const status = err?.status || err?.statusCode || 0;
        const isRateLimited = status === 429;
        const isTransient = status === 503 || status === 502 || status === 504 || err?.code === 'ECONNRESET';

        if ((isRateLimited || isTransient) && attempt <= this.maxRetries) {
          // Read Retry-After header or compute exponential backoff
          const retryAfterHeader = err?.headers?.get?.('retry-after');
          let delayMs = isRateLimited ? 2500 * attempt : 1500 * attempt;

          if (retryAfterHeader) {
            const parsedSeconds = parseInt(retryAfterHeader, 10);
            if (!isNaN(parsedSeconds) && parsedSeconds > 0) {
              delayMs = parsedSeconds * 1000 + 200;
            }
          }

          console.warn(
            `[RateLimiter:${this.name}] HTTP ${status} encountered on attempt ${attempt}/${this.maxRetries}. Backing off for ${delayMs}ms...`
          );
          await new Promise((r) => setTimeout(r, delayMs));
          continue;
        }

        throw err;
      }
    }

    throw lastError;
  }

  public clearCache(): void {
    this.cache.clear();
  }
}
