import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { CoverImage, SearchQuery, UnifiedAlbumMetadata, UnifiedTrack } from '../types';

export class AppleMusicProvider extends BaseProvider {
  public readonly name = 'AppleMusic';
  public readonly type = 'visual' as const;
  public readonly isFreeOrPublic = true;
  public readonly description =
    'Commercial artwork provider offering up to 1400x1400 high-res album covers and 30-second audio stream previews without requiring an API key.';

  constructor() {
    super(
      new RateLimiter({
        name: 'AppleMusic',
        minIntervalMs: config.appleMusic.minIntervalMs, // 250ms
        maxRetries: 2,
        defaultTtlMs: 60 * 60 * 1000,
      })
    );
  }

  public isConfigured(): boolean {
    return true; // No key required
  }

  /**
   * Search albums and retrieve high-res artwork (up to 1400x1400).
   */
  public async searchAlbumCovers(query: SearchQuery): Promise<CoverImage[]> {
    const term = [query.artist, query.title].filter(Boolean).join(' ') || query.query || '';
    if (!term.trim()) return [];

    const url = `${config.appleMusic.baseUrl}/search?term=${encodeURIComponent(
      term
    )}&entity=album&limit=6`;

    try {
      const data = await this.fetchJson<any>(url, {}, `itunes_${term.toLowerCase()}`);

      if (!data || !Array.isArray(data.results)) return [];

      const covers: CoverImage[] = [];

      for (const item of data.results) {
        if (item.artworkUrl100) {
          // Replace 100x100bb with 1400x1400bb for pristine vinyl cover resolution
          const hiResUrl = item.artworkUrl100
            .replace(/\/\d+x\d+bb\./, '/1400x1400bb.')
            .replace(/\/\d+x\d+\./, '/1400x1400.');

          covers.push({
            url: hiResUrl,
            source: 'apple',
            type: 'front',
            width: 1400,
            height: 1400,
            isHighRes: true,
          });
        }
      }

      return covers;
    } catch (err) {
      console.warn('[AppleMusic] Search failed:', err);
      return [];
    }
  }

  /**
   * Resolve 30-second audio preview for turntable player.
   */
  public async getAudioPreview(
    artist: string,
    title: string
  ): Promise<{ previewUrl?: string; trackTitle?: string } | null> {
    const term = `${artist} ${title}`.trim();
    if (!term) return null;

    const url = `${config.appleMusic.baseUrl}/search?term=${encodeURIComponent(
      term
    )}&entity=song&limit=3`;

    try {
      const data = await this.fetchJson<any>(url, {}, `itunes_song_${term.toLowerCase()}`);

      if (!data || !Array.isArray(data.results) || data.results.length === 0) {
        return null;
      }

      const match = data.results[0];
      return {
        previewUrl: match.previewUrl,
        trackTitle: match.trackName,
      };
    } catch (err) {
      return null;
    }
  }
}
