import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { CoverImage, SearchQuery, UnifiedAlbumMetadata } from '../types';

export class SpotifyProvider extends BaseProvider {
  public readonly name = 'Spotify';
  public readonly type = 'visual' as const;
  public readonly isFreeOrPublic = false;
  public readonly description =
    'Commercial streaming database providing pristine 640x640 album artwork and catalog IDs via Client Credentials flow.';

  private accessToken: string | null = null;
  private tokenExpiresAt: number = 0;

  constructor() {
    super(
      new RateLimiter({
        name: 'Spotify',
        minIntervalMs: 200,
        maxRetries: 2,
        defaultTtlMs: 60 * 60 * 1000,
      })
    );
  }

  public isConfigured(): boolean {
    return Boolean(config.spotify.clientId && config.spotify.clientSecret);
  }

  /**
   * Acquire or refresh client credentials bearer token.
   */
  private async getValidToken(): Promise<string | null> {
    if (!this.isConfigured()) return null;

    if (this.accessToken && Date.now() < this.tokenExpiresAt - 60000) {
      return this.accessToken;
    }

    try {
      const creds = Buffer.from(
        `${config.spotify.clientId}:${config.spotify.clientSecret}`
      ).toString('base64');

      const res = await fetch(config.spotify.tokenUrl, {
        method: 'POST',
        headers: {
          Authorization: `Basic ${creds}`,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: 'grant_type=client_credentials',
      });

      if (!res.ok) {
        console.warn(`[Spotify] Token request failed with HTTP ${res.status}`);
        return null;
      }

      const data = (await res.json()) as any;
      if (data && data.access_token) {
        this.accessToken = data.access_token;
        this.tokenExpiresAt = Date.now() + (data.expires_in || 3600) * 1000;
        return this.accessToken;
      }
    } catch (err) {
      console.warn('[Spotify] Error obtaining access token:', err);
    }

    return null;
  }

  /**
   * Search albums and retrieve 640x640 commercial artwork.
   */
  public async searchAlbumCovers(query: SearchQuery): Promise<CoverImage[]> {
    const token = await this.getValidToken();
    if (!token) return [];

    let q = '';
    if (query.title && query.artist) {
      q = `album:${query.title} artist:${query.artist}`;
    } else if (query.title) {
      q = query.title;
    } else if (query.query) {
      q = query.query;
    }

    if (!q) return [];

    const url = `${config.spotify.baseUrl}/search?q=${encodeURIComponent(
      q
    )}&type=album&limit=5`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
        `spotify_${q.toLowerCase()}`
      );

      if (!data || !data.albums || !Array.isArray(data.albums.items)) return [];

      const covers: CoverImage[] = [];

      for (const item of data.albums.items) {
        if (Array.isArray(item.images)) {
          for (const img of item.images) {
            if (img.url) {
              covers.push({
                url: img.url,
                source: 'spotify',
                type: 'front',
                width: img.width || 640,
                height: img.height || 640,
                isHighRes: (img.width || 0) >= 600,
              });
            }
          }
        }
      }

      return covers;
    } catch (err) {
      console.warn('[Spotify] Album search failed:', err);
      return [];
    }
  }
}
