import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { SearchQuery, UnifiedAlbumMetadata, UnifiedTrack, CoverImage } from '../types';

export class DiscogsProvider extends BaseProvider {
  public readonly name = 'Discogs';
  public readonly type = 'core' as const;
  public readonly isFreeOrPublic = false;
  public readonly description =
    'Specialized physical release catalog for identifying vinyl pressings, matrix numbers, catalog codes, and rare editions.';

  constructor() {
    super(
      new RateLimiter({
        name: 'Discogs',
        minIntervalMs: config.discogs.minIntervalMs, // 250ms with token or 1000ms
        maxRetries: 3,
        defaultTtlMs: 30 * 60 * 1000,
      })
    );
  }

  public isConfigured(): boolean {
    return true; // Can operate unauthenticated at lower rate limit or with token
  }

  private getHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      'User-Agent': config.discogs.userAgent,
      Accept: 'application/vnd.discogs.v2.discogs+json',
    };
    if (config.discogs.token) {
      headers['Authorization'] = `Discogs token=${config.discogs.token}`;
    }
    return headers;
  }

  /**
   * Search Discogs database with vinyl prioritization.
   */
  public async searchReleases(query: SearchQuery): Promise<UnifiedAlbumMetadata[]> {
    const params = new URLSearchParams();
    params.set('type', 'release');
    params.set('per_page', '10');

    if (query.barcode) {
      params.set('barcode', query.barcode.trim());
    } else if (query.catalogNumber) {
      params.set('catno', query.catalogNumber.trim());
    } else {
      if (query.artist) params.set('artist', query.artist.trim());
      if (query.title) params.set('release_title', query.title.trim());
      if (query.format) {
        params.set('format', query.format);
      } else {
        params.set('format', 'Vinyl');
      }
    }

    const url = `${config.discogs.baseUrl}/database/search?${params.toString()}`;

    try {
      const data = await this.fetchJson<any>(url, {
        headers: this.getHeaders(),
      });

      if (!data || !Array.isArray(data.results)) return [];

      return data.results.map((r: any) => this.mapResultToUnified(r));
    } catch (err) {
      console.warn('[Discogs Provider] Search failed:', err);
      return [];
    }
  }

  /**
   * Fetch full release details including tracks, vinyl sides, and extra artwork.
   */
  public async getReleaseDetails(discogsId: number | string): Promise<UnifiedAlbumMetadata | null> {
    const id = parseInt(String(discogsId), 10);
    if (!id) return null;

    const url = `${config.discogs.baseUrl}/releases/${id}`;

    try {
      const data = await this.fetchJson<any>(url, {
        headers: this.getHeaders(),
      });

      if (!data || data.id !== id) return null;

      const tracks: UnifiedTrack[] = [];
      if (Array.isArray(data.tracklist)) {
        data.tracklist.forEach((t: any) => {
          if (t.type_ === 'track' || !t.type_) {
            tracks.push({
              position: t.position || '',
              title: t.title || 'Traccia senza titolo',
              duration: t.duration || undefined,
            });
          }
        });
      }

      const covers: CoverImage[] = [];
      if (Array.isArray(data.images)) {
        data.images.forEach((img: any) => {
          if (img.uri || img.resource_url) {
            covers.push({
              url: img.uri || img.resource_url,
              source: 'discogs',
              type: img.type === 'primary' ? 'front' : 'other',
              width: img.width,
              height: img.height,
            });
          }
        });
      }

      const artist =
        Array.isArray(data.artists) && data.artists.length > 0
          ? data.artists.map((a: any) => a.name.replace(/\s*\(\d+\)$/, '')).join(', ')
          : 'Artista Sconosciuto';

      return {
        id: `discogs_${data.id}`,
        source: 'discogs',
        discogsId: data.id,
        artist,
        title: data.title || 'Senza Titolo',
        year: data.year ? String(data.year) : undefined,
        releasedDate: data.released || undefined,
        label: Array.isArray(data.labels) && data.labels.length > 0 ? data.labels[0]?.name : undefined,
        catalogNumber:
          Array.isArray(data.labels) && data.labels.length > 0 ? data.labels[0]?.catno : undefined,
        country: data.country || undefined,
        format:
          Array.isArray(data.formats) && data.formats.length > 0
            ? data.formats.map((f: any) => [f.name, ...(f.descriptions || [])].join(', ')).join('; ')
            : 'Vinyl',
        genre: Array.isArray(data.genres) ? data.genres.join(', ') : undefined,
        styles: Array.isArray(data.styles) ? data.styles : undefined,
        coverUrl: covers[0]?.url || data.thumb || undefined,
        covers,
        tracks,
        description: data.notes || undefined,
      };
    } catch (err) {
      console.warn(`[Discogs Provider] Failed to fetch release ${id}:`, err);
      return null;
    }
  }

  private mapResultToUnified(r: any): UnifiedAlbumMetadata {
    let artist = 'Artista Sconosciuto';
    let title = r.title || 'Senza Titolo';

    if (r.title && r.title.includes(' - ')) {
      const parts = r.title.split(' - ');
      artist = parts[0].trim().replace(/\s*\(\d+\)$/, '');
      title = parts.slice(1).join(' - ').trim();
    }

    return {
      id: `discogs_${r.id}`,
      source: 'discogs',
      discogsId: r.id,
      artist,
      title,
      year: r.year ? String(r.year) : undefined,
      country: r.country || undefined,
      catalogNumber: r.catno || undefined,
      barcode: Array.isArray(r.barcode) ? r.barcode[0] : undefined,
      format: Array.isArray(r.format) ? r.format.join(', ') : 'Vinyl',
      genre: Array.isArray(r.genre) ? r.genre.join(', ') : undefined,
      coverUrl: r.cover_image || r.thumb || undefined,
    };
  }
}
