import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { SyncedLyricLine, TrackLyrics } from '../types';

export class LyricsProvider extends BaseProvider {
  public readonly name = 'Lyrics';
  public readonly type = 'lyrics' as const;
  public readonly isFreeOrPublic = true;
  public readonly description =
    'Multi-source lyrics provider integrating LRCLIB (synchronized timestamps), Genius API, and Musixmatch.';

  constructor() {
    super(
      new RateLimiter({
        name: 'Lyrics',
        minIntervalMs: 250,
        maxRetries: 2,
        defaultTtlMs: 24 * 60 * 60 * 1000, // cache lyrics for 24h
      })
    );
  }

  public isConfigured(): boolean {
    return true; // LRCLIB is open/free out-of-the-box; Genius/Musixmatch can be enabled via .env
  }

  /**
   * Parse standard LRC format string into timestamped lines.
   */
  public static parseLrc(lrcText: string): SyncedLyricLine[] {
    if (!lrcText) return [];

    const lines = lrcText.split(/\r?\n/);
    const parsed: SyncedLyricLine[] = [];
    const timeRegex = /\[(\d{2}):(\d{2})\.?(\d{2,3})?\]/g;

    for (const line of lines) {
      const match = timeRegex.exec(line);
      if (match) {
        const mins = parseInt(match[1], 10);
        const secs = parseInt(match[2], 10);
        const millis = match[3] ? parseInt(match[3].padEnd(3, '0').slice(0, 3), 10) : 0;
        const totalSeconds = mins * 60 + secs + millis / 1000;
        const text = line.replace(/\[\d{2}:\d{2}\.?\d{2,3}?\]/g, '').trim();

        if (text) {
          parsed.push({
            seconds: totalSeconds,
            text,
            timeTag: `[${match[1]}:${match[2]}]`,
          });
        }
      }
      timeRegex.lastIndex = 0;
    }

    return parsed.sort((a, b) => a.seconds - b.seconds);
  }

  /**
   * Retrieve lyrics with fallback: LRCLIB (synced) -> Genius -> Musixmatch.
   */
  public async getLyrics(
    artist: string,
    trackTitle: string,
    albumTitle?: string
  ): Promise<TrackLyrics | null> {
    if (!artist || !trackTitle) return null;

    const cleanArtist = artist.replace(/\s*\(\d+\)$/, '').trim();
    const cleanTitle = trackTitle
      .replace(/\s*-\s*Remastered.*$/i, '')
      .replace(/\s*\(Remastered.*\)$/i, '')
      .replace(/\s*\[.*\]/g, '')
      .trim();

    // 1. Primary: LRCLIB (provides both plain and synchronized lyrics free without token)
    try {
      const lrclibRes = await this.fetchFromLrclib(cleanArtist, cleanTitle, albumTitle);
      if (lrclibRes) return lrclibRes;
    } catch (e) {
      // Fallback
    }

    // 2. Secondary: Genius API (if configured)
    if (config.lyrics.geniusToken) {
      try {
        const geniusRes = await this.fetchFromGenius(cleanArtist, cleanTitle);
        if (geniusRes) return geniusRes;
      } catch (e) {
        // Fallback
      }
    }

    // 3. Tertiary: Musixmatch API (if configured)
    if (config.lyrics.musixmatchKey) {
      try {
        const musixmatchRes = await this.fetchFromMusixmatch(cleanArtist, cleanTitle);
        if (musixmatchRes) return musixmatchRes;
      } catch (e) {
        // Fallback
      }
    }

    return null;
  }

  /**
   * Fetch from LRCLIB
   */
  private async fetchFromLrclib(
    artist: string,
    title: string,
    album?: string
  ): Promise<TrackLyrics | null> {
    const params = new URLSearchParams({
      artist_name: artist,
      track_name: title,
    });
    if (album) params.set('album_name', album);

    const url = `${config.lyrics.lrclibBaseUrl}/get?${params.toString()}`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {
          headers: {
            'User-Agent': config.musicBrainz.userAgent,
          },
        },
        `lrclib_${artist.toLowerCase()}__${title.toLowerCase()}`
      );

      if (!data || (!data.plainLyrics && !data.syncedLyrics)) {
        return null;
      }

      const syncedLines = data.syncedLyrics
        ? LyricsProvider.parseLrc(data.syncedLyrics)
        : undefined;

      return {
        trackTitle: data.trackName || title,
        artistName: data.artistName || artist,
        albumTitle: data.albumName || album,
        durationMs: data.duration ? Math.round(data.duration * 1000) : undefined,
        plainLyrics: data.plainLyrics || undefined,
        syncedLyrics: syncedLines && syncedLines.length > 0 ? syncedLines : undefined,
        rawLrc: data.syncedLyrics || undefined,
        source: 'lrclib',
      };
    } catch (err) {
      return null;
    }
  }

  /**
   * Fetch track info from Genius API
   */
  private async fetchFromGenius(artist: string, title: string): Promise<TrackLyrics | null> {
    if (!config.lyrics.geniusToken) return null;

    const q = `${artist} ${title}`;
    const url = `https://api.genius.com/search?q=${encodeURIComponent(q)}`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {
          headers: {
            Authorization: `Bearer ${config.lyrics.geniusToken}`,
          },
        },
        `genius_${q.toLowerCase()}`
      );

      const hits = data?.response?.hits;
      if (!Array.isArray(hits) || hits.length === 0) return null;

      const hit = hits[0].result;
      return {
        trackTitle: hit.title || title,
        artistName: hit.primary_artist?.name || artist,
        url: hit.url,
        source: 'genius',
        plainLyrics: hit.lyrics_state === 'complete' ? `Testo visualizzabile su Genius: ${hit.url}` : undefined,
      };
    } catch (err) {
      return null;
    }
  }

  /**
   * Fetch from Musixmatch API
   */
  private async fetchFromMusixmatch(artist: string, title: string): Promise<TrackLyrics | null> {
    if (!config.lyrics.musixmatchKey) return null;

    const url = `https://api.musixmatch.com/ws/1.1/matcher.lyrics.get?q_track=${encodeURIComponent(
      title
    )}&q_artist=${encodeURIComponent(artist)}&apikey=${config.lyrics.musixmatchKey}`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {},
        `musixmatch_${artist.toLowerCase()}__${title.toLowerCase()}`
      );

      const body = data?.message?.body?.lyrics;
      if (!body || !body.lyrics_body) return null;

      return {
        trackTitle: title,
        artistName: artist,
        plainLyrics: body.lyrics_body,
        copyright: body.lyrics_copyright,
        url: body.backlink_url,
        source: 'musixmatch',
      };
    } catch (err) {
      return null;
    }
  }
}
