import { RateLimiter } from '../rateLimiter';
import { ProviderStatus } from '../types';

export abstract class BaseProvider {
  public abstract readonly name: string;
  public abstract readonly type: 'core' | 'visual' | 'lyrics' | 'fingerprint';
  public abstract readonly isFreeOrPublic: boolean;
  public abstract readonly description: string;

  protected rateLimiter: RateLimiter;
  protected timeoutMs: number = 8500;

  constructor(rateLimiter: RateLimiter, timeoutMs?: number) {
    this.rateLimiter = rateLimiter;
    if (timeoutMs) this.timeoutMs = timeoutMs;
  }

  public abstract isConfigured(): boolean;

  public getStatus(): ProviderStatus {
    const stats = this.rateLimiter.getStats();
    return {
      name: this.name,
      type: this.type,
      enabled: this.isConfigured(),
      hasApiKey: !this.isFreeOrPublic,
      isFreeOrPublic: this.isFreeOrPublic,
      rateLimit: `Min interval ${stats.minIntervalMs}ms`,
      lastRequestAt: stats.lastRequestTimestamp
        ? new Date(stats.lastRequestTimestamp).toISOString()
        : undefined,
      totalRequests: stats.totalRequests,
      totalErrors: stats.totalErrors,
      description: this.description,
    };
  }

  /**
   * Performs an HTTP GET request with Rate Limiting, timeout, and in-memory caching.
   */
  protected async fetchJson<T>(
    url: string,
    options: RequestInit = {},
    cacheKey: string | null = null,
    ttlMs?: number
  ): Promise<T> {
    const key = cacheKey ?? url;

    return this.rateLimiter.execute(
      key,
      async () => {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), this.timeoutMs);

        try {
          const res = await fetch(url, {
            ...options,
            signal: controller.signal,
          });

          if (!res.ok) {
            const err: any = new Error(
              `[${this.name}] HTTP ${res.status}: ${res.statusText} for ${url}`
            );
            err.status = res.status;
            err.statusCode = res.status;
            err.headers = res.headers;
            throw err;
          }

          const data = (await res.json()) as T;
          return data;
        } finally {
          clearTimeout(timeout);
        }
      },
      ttlMs
    );
  }
}
