import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { CoverImage } from '../types';

export class CoverArtArchiveProvider extends BaseProvider {
  public readonly name = 'CoverArtArchive';
  public readonly type = 'visual' as const;
  public readonly isFreeOrPublic = true;
  public readonly description =
    'Official high-resolution artwork repository connected directly to MusicBrainz releases via MBID.';

  constructor() {
    super(
      new RateLimiter({
        name: 'CoverArtArchive',
        minIntervalMs: config.coverArtArchive.minIntervalMs, // 200ms
        maxRetries: 2,
        defaultTtlMs: 60 * 60 * 1000, // 1 hour cache
      })
    );
  }

  public isConfigured(): boolean {
    return true; // Free, public, no key needed
  }

  /**
   * Fetch all images (front, back, booklet, vinyl media) associated with a MusicBrainz MBID.
   */
  public async getCoversByMbid(mbid: string): Promise<CoverImage[]> {
    if (!mbid) return [];

    const url = `${config.coverArtArchive.baseUrl}/release/${mbid}`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {
          headers: {
            Accept: 'application/json',
            'User-Agent': config.musicBrainz.userAgent,
          },
        },
        `caa_${mbid}`
      );

      if (!data || !Array.isArray(data.images)) return [];

      const results: CoverImage[] = [];

      for (const img of data.images) {
        let type: CoverImage['type'] = 'other';
        if (img.front) type = 'front';
        else if (img.back) type = 'back';
        else if (Array.isArray(img.types)) {
          if (img.types.includes('Booklet')) type = 'booklet';
          else if (img.types.includes('Medium')) type = 'medium';
          else if (img.types.includes('Tray')) type = 'tray';
          else if (img.types.includes('Liner')) type = 'liner';
        }

        // Prefer 1200px or 500px thumbnail or original image
        const bestUrl =
          img.thumbnails?.['1200'] ||
          img.thumbnails?.large ||
          img.thumbnails?.['500'] ||
          img.image;

        if (bestUrl) {
          results.push({
            url: bestUrl,
            source: 'coverartarchive',
            type,
            isHighRes: Boolean(img.thumbnails?.['1200'] || img.image),
          });
        }
      }

      return results;
    } catch (err: any) {
      // 404 is normal for releases without archived artwork yet
      if (err?.status !== 404) {
        console.warn(`[CoverArtArchive] Failed to fetch covers for ${mbid}:`, err?.message || err);
      }
      return [];
    }
  }

  /**
   * Get direct front image URL if available.
   */
  public getDirectFrontUrl(mbid: string): string {
    return `${config.coverArtArchive.baseUrl}/release/${mbid}/front-500`;
  }
}
