import { BaseProvider } from './base';
import { RateLimiter } from '../rateLimiter';
import { config } from '../config';
import { ArtistBio, SearchQuery, UnifiedAlbumMetadata, CoverImage } from '../types';

export class TheAudioDbProvider extends BaseProvider {
  public readonly name = 'TheAudioDB';
  public readonly type = 'core' as const;
  public readonly isFreeOrPublic = true;
  public readonly description =
    'Community music database specializing in multi-language artist biographies (Italian/English), album reviews, and high-res promotional fanart.';

  constructor() {
    super(
      new RateLimiter({
        name: 'TheAudioDB',
        minIntervalMs: config.theAudioDb.minIntervalMs, // 500ms
        maxRetries: 2,
        defaultTtlMs: 60 * 60 * 1000, // 1 hour cache
      })
    );
  }

  public isConfigured(): boolean {
    return Boolean(config.theAudioDb.apiKey);
  }

  /**
   * Get artist biography, banners, fanart, logo, formed year in Italian and English.
   */
  public async getArtistBio(artistName: string): Promise<ArtistBio | null> {
    if (!artistName || !this.isConfigured()) return null;

    const cleanName = artistName.replace(/\s*\(\d+\)\s*$/g, '').trim();
    const url = `${config.theAudioDb.baseUrl}/${config.theAudioDb.apiKey}/search.php?s=${encodeURIComponent(
      cleanName
    )}`;

    try {
      const data = await this.fetchJson<any>(url, {}, `tadb_artist_${cleanName.toLowerCase()}`);

      if (!data || !Array.isArray(data.artists) || data.artists.length === 0) {
        return null;
      }

      const a = data.artists[0];
      const bioIT = a.strBiographyIT ? a.strBiographyIT.trim() : undefined;
      const bioEN = a.strBiographyEN ? a.strBiographyEN.trim() : undefined;

      return {
        artistName: a.strArtist || cleanName,
        biographyIT: bioIT,
        biographyEN: bioEN,
        biography: bioIT || bioEN || 'Nessuna biografia disponibile.',
        formedYear: a.intFormedYear || undefined,
        bornYear: a.intBornYear || undefined,
        country: a.strCountry || undefined,
        genre: a.strGenre || undefined,
        style: a.strStyle || undefined,
        mood: a.strMood || undefined,
        bannerUrl: a.strArtistBanner || undefined,
        fanartUrl: a.strArtistFanart || undefined,
        logoUrl: a.strArtistLogo || undefined,
        thumbnailUrl: a.strArtistThumb || undefined,
        source: 'theaudiodb',
      };
    } catch (err) {
      console.warn(`[TheAudioDB] Failed to fetch artist bio for ${cleanName}:`, err);
      return null;
    }
  }

  /**
   * Search album by artist and title to retrieve description, genre, release year and album artwork.
   */
  public async searchAlbum(query: SearchQuery): Promise<UnifiedAlbumMetadata | null> {
    if (!query.artist || !query.title || !this.isConfigured()) return null;

    const cleanArtist = query.artist.replace(/\s*\(\d+\)\s*$/g, '').trim();
    const cleanAlbum = query.title.replace(/[":*?]/g, ' ').trim();

    const url = `${config.theAudioDb.baseUrl}/${config.theAudioDb.apiKey}/searchalbum.php?s=${encodeURIComponent(
      cleanArtist
    )}&a=${encodeURIComponent(cleanAlbum)}`;

    try {
      const data = await this.fetchJson<any>(
        url,
        {},
        `tadb_album_${cleanArtist.toLowerCase()}__${cleanAlbum.toLowerCase()}`
      );

      if (!data || !Array.isArray(data.album) || data.album.length === 0) {
        return null;
      }

      const alb = data.album[0];
      const descIT = alb.strDescriptionIT ? alb.strDescriptionIT.trim() : undefined;
      const descEN = alb.strDescriptionEN ? alb.strDescriptionEN.trim() : undefined;

      const covers: CoverImage[] = [];
      if (alb.strAlbumThumb) {
        covers.push({
          url: alb.strAlbumThumb,
          source: 'theaudiodb',
          type: 'front',
          isHighRes: true,
        });
      }
      if (alb.strAlbumCDart) {
        covers.push({
          url: alb.strAlbumCDart,
          source: 'theaudiodb',
          type: 'medium',
        });
      }

      return {
        id: `tadb_${alb.idAlbum}`,
        source: 'theaudiodb',
        theAudioDbId: alb.idAlbum,
        artist: alb.strArtist || cleanArtist,
        title: alb.strAlbum || cleanAlbum,
        year: alb.intYearReleased || undefined,
        genre: alb.strGenre || undefined,
        styles: alb.strStyle ? [alb.strStyle] : undefined,
        coverUrl: alb.strAlbumThumb || undefined,
        covers,
        description: descIT || descEN || undefined,
      };
    } catch (err) {
      console.warn('[TheAudioDB] Album search failed:', err);
      return null;
    }
  }
}
